**动态选择数据库**：
```csharp
public class MultiDatabaseDbContext : DbContext
{
    private readonly string _databaseProvider;

    public MultiDatabaseDbContext(
        DbContextOptions<MultiDatabaseDbContext> options,
        IConfiguration configuration)
        : base(options)
    {
        _databaseProvider = configuration["DatabaseProvider"];
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        if (!optionsBuilder.IsConfigured)
        {
            switch (_databaseProvider)
            {
                case "SqlServer":
                    optionsBuilder.UseSqlServer(_connectionString);
                    break;
                case "Postgres":
                    optionsBuilder.UseNpgsql(_connectionString);
                    break;
                case "MySql":
                    optionsBuilder.UseMySql(_connectionString,
                        ServerVersion.AutoDetect(_connectionString));
                    break;
            }
        }
    }
}
```

## 数据库兼容性

**通用 SQL**：
```csharp
// 使用通用 SQL
await _context.Database.ExecuteSqlRawAsync(
    "UPDATE Users SET IsActive = 0 WHERE CreatedAt < {0}",
    DateTime.UtcNow.AddDays(-30));
```

**数据库特定功能**：
```csharp
// SQL Server 特定
await _context.Database.ExecuteSqlRawAsync(
    "UPDATE Users SET IsActive = 0 WHERE CreatedAt < DATEADD(day, -30, GETUTCDATE())");

// PostgreSQL 特定
await _context.Database.ExecuteSqlRawAsync(
    "UPDATE Users SET IsActive = 0 WHERE CreatedAt < NOW() - INTERVAL '30 days'");
```

**条件编译**：
```csharp
#if SQLSERVER
    options.UseSqlServer(connectionString);
#elif POSTGRES
    options.UseNpgsql(connectionString);
#endif
```


## 多租户架构

**三种隔离策略**：

**1. 数据库隔离（Database per Tenant）**：
```csharp
public class TenantDbContextFactory : IDbContextFactory<AppDbContext>
{
    private readonly ITenantService _tenantService;

    public AppDbContext CreateDbContext()
    {
        var tenant = _tenantService.GetCurrentTenant();
        var options = new DbContextOptionsBuilder<AppDbContext>()
            .UseSqlServer(tenant.ConnectionString)
            .Options;

        return new AppDbContext(options);
    }
}
```

**2. Schema 隔离**：
```csharp
public class MultiTenantDbContext : DbContext
{
    private readonly ITenantService _tenantService;

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var tenant = _tenantService.GetCurrentTenant();

        modelBuilder.HasDefaultSchema(tenant.SchemaName);

        // 或者每个实体指定 schema
        modelBuilder.Entity<User>().ToTable("Users", tenant.SchemaName);
    }
}
```

**3. 行级隔离（Row Level）**：
```csharp
public class MultiTenantDbContext : DbContext
{
    private readonly ITenantService _tenantService;

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var tenantId = _tenantService.GetCurrentTenantId();

        // 全局查询过滤器
        modelBuilder.Entity<User>().HasQueryFilter(u => u.TenantId == tenantId);
        modelBuilder.Entity<Order>().HasQueryFilter(o => o.TenantId == tenantId);
    }

    public override int SaveChanges()
    {
        // 自动设置 TenantId
        var tenantId = _tenantService.GetCurrentTenantId();
        foreach (var entry in ChangeTracker.Entries<ITenantEntity>())
        {
            if (entry.State == EntityState.Added)
            {
                entry.Entity.TenantId = tenantId;
            }
        }

        return base.SaveChanges();
    }
}

public interface ITenantEntity
{
    int TenantId { get; set; }
}

public class User : ITenantEntity
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int TenantId { get; set; }
}
```

## 租户服务

```csharp
public interface ITenantService
{
    Tenant GetCurrentTenant();
    int GetCurrentTenantId();
}

public class HttpTenantService : ITenantService
{
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly TenantDbContext _tenantContext;

    public HttpTenantService(
        IHttpContextAccessor httpContextAccessor,
        TenantDbContext tenantContext)
    {
        _httpContextAccessor = httpContextAccessor;
        _tenantContext = tenantContext;
    }

    public Tenant GetCurrentTenant()
    {
        var tenantId = GetCurrentTenantId();
        return _tenantContext.Tenants.Find(tenantId);
    }

    public int GetCurrentTenantId()
    {
        // 从 Header、Claim 或子域名获取租户标识
        var tenantIdentifier = _httpContextAccessor.HttpContext.Request.Headers["X-Tenant-Id"].FirstOrDefault();

        if (int.TryParse(tenantIdentifier, out var tenantId))
        {
            return tenantId;
        }

        // 从子域名获取
        var host = _httpContextAccessor.HttpContext.Request.Host.Host;
        var subdomain = host.Split('.')[0];

        return _tenantContext.Tenants
            .Where(t => t.Subdomain == subdomain)
            .Select(t => t.Id)
            .FirstOrDefault();
    }
}
```


## 租户中间件

```csharp
public class TenantMiddleware
{
    private readonly RequestDelegate _next;

    public TenantMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context, ITenantService tenantService)
    {
        var tenant = tenantService.GetCurrentTenant();
        if (tenant == null)
        {
            context.Response.StatusCode = 404;
            await context.Response.WriteAsync("租户不存在");
            return;
        }

        // 设置租户上下文
        context.Items["Tenant"] = tenant;

        await _next(context);
    }
}
```


## 数据库迁移策略

**数据库隔离**：每个租户独立迁移
```csharp
foreach (var tenant in tenants)
{
    using var context = CreateDbContextForTenant(tenant);
    await context.Database.MigrateAsync();
}
```

**行级隔离**：共享数据库，统一迁移
```csharp
using var context = serviceProvider.GetRequiredService<AppDbContext>();
await context.Database.MigrateAsync();
```


## 最佳实践

1. **选择合适的隔离策略**：根据安全需求和成本选择
2. **使用全局查询过滤器**：自动过滤租户数据
3. **自动设置租户 ID**：在 SaveChanges 时自动设置
4. **租户配置管理**：存储租户特定配置
5. **数据库连接池**：优化多数据库连接

using System;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace MultiDatabaseTenantDemo
{
    // 租户实体
    public class Tenant
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Subdomain { get; set; }
        public string ConnectionString { get; set; }
        public string SchemaName { get; set; }
        public bool IsActive { get; set; } = true;
    }

    // 租户实体接口
    public interface ITenantEntity
    {
        int TenantId { get; set; }
    }

    // 租户服务接口
    public interface ITenantService
    {
        Tenant GetCurrentTenant();
        int GetCurrentTenantId();
    }

    // HTTP 租户服务实现
    public class HttpTenantService : ITenantService
    {
        private readonly IHttpContextAccessor _httpContextAccessor;
        private readonly TenantDbContext _tenantContext;

        public HttpTenantService(
            IHttpContextAccessor httpContextAccessor,
            TenantDbContext tenantContext)
        {
            _httpContextAccessor = httpContextAccessor;
            _tenantContext = tenantContext;
        }

        public Tenant GetCurrentTenant()
        {
            var tenantId = GetCurrentTenantId();
            return _tenantContext.Tenants.Find(tenantId);
        }

        public int GetCurrentTenantId()
        {
            var context = _httpContextAccessor.HttpContext;

            // 从 Header 获取
            var tenantIdHeader = context.Request.Headers["X-Tenant-Id"].FirstOrDefault();
            if (int.TryParse(tenantIdHeader, out var tenantId))
            {
                return tenantId;
            }

            // 从子域名获取
            var host = context.Request.Host.Host;
            var subdomain = host.Split('.')[0];

            return _tenantContext.Tenants
                .Where(t => t.Subdomain == subdomain && t.IsActive)
                .Select(t => t.Id)
                .FirstOrDefault();
        }
    }

    // 租户 DbContext
    public class TenantDbContext : DbContext
    {
        public DbSet<Tenant> Tenants { get; set; }

        public TenantDbContext(DbContextOptions<TenantDbContext> options)
            : base(options) { }
    }

    // 多租户应用 DbContext（行级隔离）
    public class MultiTenantAppDbContext : DbContext
    {
        private readonly ITenantService _tenantService;

        public MultiTenantAppDbContext(
            DbContextOptions<MultiTenantAppDbContext> options,
            ITenantService tenantService)
            : base(options)
        {
            _tenantService = tenantService;
        }

        public DbSet<User> Users { get; set; }
        public DbSet<Order> Orders { get; set; }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            var tenantId = _tenantService.GetCurrentTenantId();

            // 全局查询过滤器
            modelBuilder.Entity<User>().HasQueryFilter(u => u.TenantId == tenantId);
            modelBuilder.Entity<Order>().HasQueryFilter(o => o.TenantId == tenantId);

            // 配置实体
            modelBuilder.Entity<User>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.HasIndex(e => new { e.TenantId, e.Email }).IsUnique();
            });

            modelBuilder.Entity<Order>(entity =>
            {
                entity.HasKey(e => e.Id);
                entity.HasOne(e => e.User)
                    .WithMany(u => u.Orders)
                    .HasForeignKey(e => new { e.TenantId, e.UserId });
            });
        }

        public override int SaveChanges()
        {
            SetTenantId();
            return base.SaveChanges();
        }

        public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
        {
            SetTenantId();
            return await base.SaveChangesAsync(cancellationToken);
        }

        private void SetTenantId()
        {
            var tenantId = _tenantService.GetCurrentTenantId();

            foreach (var entry in ChangeTracker.Entries<ITenantEntity>())
            {
                if (entry.State == EntityState.Added)
                {
                    entry.Entity.TenantId = tenantId;
                }
            }
        }
    }

    // 数据库隔离的 DbContext 工厂
    public class TenantDbContextFactory
    {
        private readonly ITenantService _tenantService;

        public TenantDbContextFactory(ITenantService tenantService)
        {
            _tenantService = tenantService;
        }

        public MultiTenantAppDbContext CreateDbContext()
        {
            var tenant = _tenantService.GetCurrentTenant();
            var options = new DbContextOptionsBuilder<MultiTenantAppDbContext>()
                .UseSqlServer(tenant.ConnectionString)
                .Options;

            return new MultiTenantAppDbContext(options, _tenantService);
        }
    }

    // 多数据库支持的 DbContext
    public class FlexibleDbContext : DbContext
    {
        private readonly string _provider;
        private readonly string _connectionString;

        public FlexibleDbContext(
            DbContextOptions<FlexibleDbContext> options,
            IConfiguration configuration)
            : base(options)
        {
            _provider = configuration["Database:Provider"];
            _connectionString = configuration["Database:ConnectionString"];
        }

        public DbSet<User> Users { get; set; }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            if (!optionsBuilder.IsConfigured)
            {
                switch (_provider?.ToLower())
                {
                    case "sqlserver":
                        optionsBuilder.UseSqlServer(_connectionString);
                        break;
                    case "postgres":
                        optionsBuilder.UseNpgsql(_connectionString);
                        break;
                    case "mysql":
                        optionsBuilder.UseMySql(_connectionString,
                            ServerVersion.AutoDetect(_connectionString));
                        break;
                    case "sqlite":
                        optionsBuilder.UseSqlite(_connectionString);
                        break;
                    default:
                        optionsBuilder.UseInMemoryDatabase("Default");
                        break;
                }
            }
        }
    }

    // 实体类
    public class User : ITenantEntity
    {
        public int Id { get; set; }
        public int TenantId { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
        public ICollection<Order> Orders { get; set; } = new List<Order>();
    }

    public class Order : ITenantEntity
    {
        public int Id { get; set; }
        public int TenantId { get; set; }
        public int UserId { get; set; }
        public User User { get; set; }
        public decimal Amount { get; set; }
    }

    // 租户中间件
    public class TenantMiddleware
    {
        private readonly RequestDelegate _next;

        public TenantMiddleware(RequestDelegate next)
        {
            _next = next;
        }

        public async Task InvokeAsync(HttpContext context, ITenantService tenantService)
        {
            var tenant = tenantService.GetCurrentTenant();
            if (tenant == null || !tenant.IsActive)
            {
                context.Response.StatusCode = 404;
                await context.Response.WriteAsync("租户不存在或已禁用");
                return;
            }

            context.Items["Tenant"] = tenant;
            await _next(context);
        }
    }

    // 服务注册
    public static class MultiTenantServiceCollectionExtensions
    {
        public static IServiceCollection AddMultiTenant(
            this IServiceCollection services,
            IConfiguration configuration)
        {
            services.AddHttpContextAccessor();
            services.AddScoped<ITenantService, HttpTenantService>();

            // 租户配置数据库
            services.AddDbContext<TenantDbContext>(options =>
                options.UseSqlServer(configuration.GetConnectionString("TenantDb")));

            // 应用数据库（行级隔离）
            services.AddDbContext<MultiTenantAppDbContext>((provider, options) =>
            {
                var tenantService = provider.GetRequiredService<ITenantService>();
                var tenant = tenantService.GetCurrentTenant();

                if (tenant != null)
                {
                    options.UseSqlServer(tenant.ConnectionString);
                }
                else
                {
                    options.UseSqlServer(configuration.GetConnectionString("Default"));
                }
            });

            // 数据库隔离工厂
            services.AddScoped<TenantDbContextFactory>();

            return services;
        }
    }
}
